// ─────────────────────────────────────────────────────────────────
// SHARED COMPONENTS
// ─────────────────────────────────────────────────────────────────

function RiskBadge({ level }) {
  if (!level) return null;
  return (
    <span className={`badge badge-${level}`}>
      <span className={`dot dot-${level}`} />
      {level.toUpperCase()}
    </span>
  );
}

function Spinner() { return <div className="spinner" />; }
function FullSpinner() { return <div className="full-spinner"><Spinner /></div>; }

function ErrorState({ message, onRetry }) {
  if (!message) return null;
  return (
    <div className="error-card">
      <div style={{fontWeight:700, marginBottom:4}}>Something went wrong</div>
      <div style={{fontSize:13}}>{message}</div>
      {onRetry && <button className="btn btn-ghost btn-sm" style={{marginTop:10}} onClick={onRetry}>Try again</button>}
    </div>
  );
}

function EmptyState({ title, text, action }) {
  return <div className="empty-state"><div style={{fontWeight:700, color:'var(--slate)', marginBottom:4}}>{title}</div><div>{text}</div>{action}</div>;
}

function formatDate(value) {
  if (!value) return '—';
  const d = new Date(value);
  return Number.isNaN(d.getTime()) ? String(value) : d.toLocaleString();
}

function formatDuration(value) {
  if (value === undefined || value === null || value === '') return '—';
  const n = Number(value);
  if (!Number.isFinite(n)) return String(value);
  const seconds = Math.max(0, Math.round(n));
  const m = Math.floor(seconds / 60);
  const s = seconds % 60;
  return m ? `${m}m ${s}s` : `${s}s`;
}

function normalizeIsraeliPhone(raw) {
  return String(raw || '').replace(/[\s\-()]/g, '');
}

function validateIsraeliPhone(raw) {
  const phone = normalizeIsraeliPhone(raw);
  if (!phone) return 'Guardian phone is required.';
  if (phone.startsWith('0')) return 'Use international format: +972..., not a local 050/052 number.';
  if (!phone.startsWith('+972')) return 'Phone must start with +972.';
  if (!/^\+972[2-9]\d{7,8}$/.test(phone)) return 'Phone must be a valid Israeli E.164 number, for example +972507776403.';
  const digits = phone.slice(1);
  if (/^(\d)\1{8,}$/.test(digits) || /123123|123456|000000|111111/.test(digits)) return 'This looks like a fake/test phone number.';
  return '';
}

function eventSignals(ev) {
  return (ev?.detectedSignals || ev?.topics || ev?.detectedTopics || []).filter(Boolean);
}

function eventTranscript(ev) {
  const t = ev?.transcript || ev?.transcriptText || ev?.conversation || [];
  if (Array.isArray(t)) return t.map((line, i) => typeof line === 'string' ? { speaker: `Line ${i+1}`, text: line } : line);
  if (typeof t === 'string') return t.split(/\n+/).filter(Boolean).map((line, i) => ({ speaker: `Line ${i+1}`, text: line }));
  return [];
}

function eventAlertSent(ev) {
  return Boolean(ev?.guardianNotified || ev?.shouldAlert || ev?.alertSent || ev?.action === 'alert_sent' || ev?.action === 'disconnected');
}

function eventContactId(ev) {
  return ev?.contactId || ev?.connectContactId || ev?.callId || ev?.eventId || '—';
}

