function Register() {
  const navigate = useNavigate();
  const [form, setForm]       = useState({ name: '', email: '', password: '', confirm: '' });
  const [error, setError]     = useState('');
  const [loading, setLoading] = useState(false);

  const set = (k) => (e) => setForm(f => ({ ...f, [k]: e.target.value }));

  async function submit(e) {
    e.preventDefault();
    setError('');
    if (form.password !== form.confirm) return setError('Passwords do not match.');
    if (form.password.length < 8)       return setError('Password must be at least 8 characters.');
    setLoading(true);
    try {
      // cognitoRegister → Cognito signUp → sends verification email
      // On email confirm → PostConfirmation Lambda → DynamoDB record created
      const result = await cognitoRegister({ name: form.name, email: form.email, password: form.password });
      sessionStorage.setItem('aisg_pending_signup', JSON.stringify({
        username: result.username,
        email: result.email,
        name: form.name.trim(),
        createdAt: Date.now()
      }));
      navigate('/confirm', { state: { username: result.username, email: result.email, name: form.name.trim() } });
    } catch (err) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  }

  return (
    <div className="auth-bg">
      <div className="auth-left">
        <div className="big">Your safety<br/>starts here.</div>
        <div className="sub">Create your SilentGuard account. An admin can assign your protected SilentGuard number after registration.</div>
      </div>
      <div className="auth-right">
        <div className="auth-card">
          <div className="auth-title">Create account</div>
          <div className="auth-sub">Join SilentGuard AI - it is free.</div>
          {error && <div className="alert alert-error">{error}</div>}
          <form onSubmit={submit}>
            {[['name','Full Name','text','Jane Smith'],['email','Email','email','you@email.com'],
              ['password','Password','password',''],['confirm','Confirm Password','password','']
            ].map(([k,label,type,ph]) => (
              <div className="form-group" key={k}>
                <label className="form-label">{label}</label>
                <input className="form-input" type={type} placeholder={ph}
                  value={form[k]} onChange={set(k)} required />
              </div>
            ))}
            <button className="btn btn-primary" style={{width:'100%',padding:'12px',marginTop:4}} disabled={loading}>
              {loading ? <Spinner /> : 'Create Account'}
            </button>
          </form>
          <hr className="divider" />
          <p className="text-muted" style={{textAlign:'center'}}>
            Already have an account? <Link to="/login" style={{color:'var(--sky)',fontWeight:500}}>Sign in</Link>
          </p>
        </div>
      </div>
    </div>
  );
}


