function ConfirmAccount() {
  const navigate = useNavigate();
  const location = window.history.state?.usr || {};
  const saved = (() => {
    try { return JSON.parse(sessionStorage.getItem('aisg_pending_signup') || '{}'); }
    catch { return {}; }
  })();

  const username = location.username || saved.username || '';
  const email    = location.email || saved.email || '';
  const [code, setCode] = useState('');
  const [error, setError] = useState('');
  const [info, setInfo] = useState(email ? `Enter the confirmation code sent to ${email}.` : 'Enter the confirmation code from your email.');
  const [loading, setLoading] = useState(false);
  const [resending, setResending] = useState(false);

  async function submit(e) {
    e.preventDefault();
    setError('');
    if (!username) return setError('Missing signup session. Please register again or ask an admin to confirm the user from Cognito.');
    if (!/^\d{6}$/.test(code.trim())) return setError('Enter the 6-digit confirmation code from your email.');
    setLoading(true);
    try {
      await confirmRegistration(username, code.trim());
      sessionStorage.removeItem('aisg_pending_signup');
      navigate('/login', { state: { message: 'Account confirmed. You can now sign in.' } });
    } catch (err) {
      setError(err.message || 'Failed to confirm account.');
    } finally {
      setLoading(false);
    }
  }

  async function resend() {
    setError('');
    if (!username) return setError('Missing signup session. Please register again to receive a new code.');
    setResending(true);
    try {
      await resendRegistrationCode(username);
      setInfo(`A new confirmation code was sent to ${email || 'your email'}.`);
    } catch (err) {
      setError(err.message || 'Could not resend confirmation code.');
    } finally {
      setResending(false);
    }
  }

  return (
    <div className="auth-bg">
      <div className="auth-left">
        <div className="big">Confirm<br/>your account.</div>
        <div className="sub">Cognito sent you a verification code. Enter it here to activate your SilentGuard account.</div>
      </div>
      <div className="auth-right">
        <div className="auth-card">
          <div className="auth-title">Confirm account</div>
          <div className="auth-sub">Use the 6-digit code from your email.</div>
          {info && <div className="alert alert-info">{info}</div>}
          {error && <div className="alert alert-error">{error}</div>}
          <form onSubmit={submit}>
            <div className="form-group">
              <label className="form-label">Email</label>
              <input className="form-input" value={email || ''} disabled placeholder="Email used for signup" />
            </div>
            <div className="form-group">
              <label className="form-label">Confirmation code</label>
              <input className="form-input" inputMode="numeric" pattern="[0-9]*" maxLength="6" placeholder="123456"
                     value={code} onChange={e => setCode(e.target.value.replace(/\D/g, '').slice(0, 6))} required />
              <div className="input-help">Check Inbox or Spam. Gmail sometimes puts Cognito emails in Spam.</div>
            </div>
            <button className="btn btn-primary" style={{width:'100%',padding:'12px',marginTop:4}} disabled={loading}>
              {loading ? <Spinner /> : 'Confirm Account'}
            </button>
          </form>
          <div className="flex-between" style={{marginTop:16}}>
            <button type="button" className="btn btn-ghost btn-sm" onClick={resend} disabled={resending}>
              {resending ? 'Sending…' : 'Resend code'}
            </button>
            <Link to="/login" className="btn btn-ghost btn-sm">Back to sign in</Link>
          </div>
        </div>
      </div>
    </div>
  );
}

