function EventDetail() {
  const { eventId } = useParams();
  const [ev, setEv]       = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const navigate = useNavigate();

  useEffect(() => {
    setLoading(true); setError('');
    getEvent(eventId)
      .then(setEv)
      .catch(e => setError(e.message || 'Could not load event details.'))
      .finally(() => setLoading(false));
  }, [eventId]);

  if (loading) return <FullSpinner />;
  if (error) return <div className="app-shell"><Sidebar/><main className="main-content"><button className="btn btn-ghost btn-sm mb-24" onClick={() => navigate(-1)}>← Back</button><ErrorState message={error}/></main></div>;
  if (!ev) return <div className="app-shell"><Sidebar/><main className="main-content"><p>Event not found.</p></main></div>;

  const actionLabel = { disconnected: '🔴 Call Disconnected Automatically', alert_sent: '🟡 Alert Sent to Guardian', none: '🟢 Logged Only' };
  const transcript = eventTranscript(ev);
  const signals = eventSignals(ev);

  return (
    <div className="app-shell">
      <Sidebar />
      <main className="main-content">
        <button className="btn btn-ghost btn-sm mb-24" onClick={() => navigate(-1)}>← Back</button>
        <div className="page-header">
          <div>
            <div className="page-title" style={{marginBottom:4}}>Event Detail</div>
            <p className="page-copy">Full call risk summary, detected signals, transcript, notification status, and Connect identifiers.</p>
          </div>
          <RiskBadge level={ev.riskLevel} />
        </div>

        <div style={{display:'grid',gridTemplateColumns:'2fr 1fr',gap:20}}>
          <div>
            <div className="card card-pad mb-24">
              <div className="card-title">Summary</div>
              <div className="event-detail-grid">
                {[['Date & Time', formatDate(ev.timestamp)],
                  ['Risk Score',  `${ev.riskScore ?? '—'} / 100`],
                  ['Risk Level',  <RiskBadge level={ev.riskLevel} />],
                  ['Action Taken', actionLabel[ev.action] || ev.action || '—'],
                  ['Alert Sent', eventAlertSent(ev) ? '✅ Yes' : '❌ No'],
                  ['Duration', formatDuration(ev.duration || ev.durationSeconds)],
                  ['Contact ID', <span className="detail-mono">{eventContactId(ev)}</span>],
                  ['Call ID', <span className="detail-mono">{ev.callId || '—'}</span>],
                ].map(([label, value]) => (
                  <div className="detail-item" key={label}><div className="detail-label">{label}</div><div className="detail-value">{value}</div></div>
                ))}
              </div>
            </div>

            <div className="card card-pad mb-24">
              <div className="card-title">Transcript</div>
              {transcript.length === 0
                ? <EmptyState title="No transcript stored" text="The call record does not include transcript text yet. Ask the analyzeScamCall owner to store transcript/segments in SilentGuardCallRecords." />
                : <div className="transcript-panel">{transcript.map((line, i) => (
                    <div className="transcript-line" key={i}>
                      <div className="transcript-speaker">{line.speaker || line.role || `Line ${i+1}`}</div>
                      <div className="transcript-text">{line.text || line.message || String(line)}</div>
                    </div>
                  ))}</div>}
            </div>

            {(ev.flaggedSegments||[]).length > 0 && (
              <div className="card card-pad">
                <div className="card-title">Flagged Segments</div>
                {ev.flaggedSegments.map((seg, i) => (
                  <div className="flagged-seg" key={i}>
                    <div className="flagged-quote">"{seg.text || seg.message}"</div>
                    <div className="flagged-reason">{seg.reason || seg.keyword || 'Flagged by risk analysis'}</div>
                  </div>
                ))}
              </div>
            )}
          </div>

          <div>
            <div className="card card-pad mb-16">
              <div className="card-title">Detected Topics / Signals</div>
              {signals.length === 0 ? <p className="text-muted">None detected.</p> : signals.map((t, i) => <span className="signal-chip" key={i}>{t}</span>)}
            </div>
            <div className="card card-pad mb-16">
              <div className="card-title">Connect / Source Metadata</div>
              {[['Contact ID', eventContactId(ev)], ['Instance ID', ev.instanceId || '—'], ['Agent Login', ev.connectAgentLogin || '—'], ['Source', ev.eventSource || '—'], ['Detail Type', ev.eventDetailType || '—']].map(([l,v]) => (
                <div key={l} style={{marginBottom:12}}><div className="detail-label">{l}</div><div className="detail-value detail-mono">{v}</div></div>
              ))}
            </div>
            {ev.reason && <div className="card card-pad"><div className="card-title">AI Reason</div><p style={{fontSize:14,color:'var(--slate)',lineHeight:1.7}}>{ev.reason}</p></div>}
          </div>
        </div>
      </main>
    </div>
  );
}

