function GuardianManagement() {
  const [profile,   setProfile]   = useState(null);
  const [loading,   setLoading]   = useState(true);
  const [saving,    setSaving]    = useState(false);
  const [msg,       setMsg]       = useState('');
  const [error,     setError]     = useState('');
  const [showAdd,   setShowAdd]   = useState(false);
  const [newGuard,  setNewGuard]  = useState({ name: '', phone: '', email: '', relationship: 'Family member' });

  const load = useCallback(() => {
    setLoading(true); setError('');
    getMe().then(setProfile).catch(e => setError(e.message)).finally(() => setLoading(false));
  }, []);

  useEffect(() => { load(); }, [load]);

  async function saveGuardian(e) {
    e.preventDefault();
    setSaving(true); setMsg(''); setError('');
    const phoneError = validateIsraeliPhone(newGuard.phone);
    if (phoneError) { setError(phoneError); setSaving(false); return; }
    try {
      const created = await createGuardian({ ...newGuard, phone: normalizeIsraeliPhone(newGuard.phone) });
      const updated = [...(profile.guardians || []), created];
      setProfile(p => ({ ...p, guardians: updated }));
      setNewGuard({ name: '', phone: '', email: '', relationship: 'Family member' });
      setShowAdd(false);
      setMsg('Guardian added successfully. Phone verification is not enabled yet; this contact is saved as active for notifications.');
    } catch(err) { setError(err.message); }
    finally { setSaving(false); }
  }

  async function removeGuardian(i) {
    const guardian = (profile.guardians || [])[i];
    const updated = (profile.guardians || []).filter((_, idx) => idx !== i);
    setSaving(true); setError(''); setMsg('');
    try {
      if (guardian?.guardianId) await deleteGuardian(guardian.guardianId);
      setProfile(p => ({ ...p, guardians: updated }));
      setMsg('Guardian removed.');
    } catch(err) { setError(err.message); }
    finally { setSaving(false); }
  }

  if (loading) return <FullSpinner />;
  if (!profile) return <div className="app-shell"><Sidebar/><main className="main-content"><ErrorState message={error || 'Profile was not returned from the API.'} onRetry={load}/></main></div>;

  const guardians = profile?.guardians || [];

  return (
    <div className="app-shell">
      <Sidebar />
      <main className="main-content">
        <div className="page-header">
          <div>
            <div className="page-title" style={{marginBottom:4}}>Guardians</div>
            <p className="page-copy">Manage trusted family members or caregivers who should receive alerts. Guardians are contact records, not separate login accounts.</p>
          </div>
          <button className="btn btn-primary" onClick={() => setShowAdd(s => !s)}>{showAdd ? 'Close Form' : '+ Add Guardian'}</button>
        </div>
        {msg && <div className="alert alert-success">{msg}</div>}
        <ErrorState message={error} />
        <ErrorState message={error} />

        <div className="summary-strip">
          <div className="mini-stat"><div className="mini-value">{guardians.length}</div><div className="mini-label">Saved guardians</div></div>
          <div className="mini-stat"><div className="mini-value">{guardians.filter(g => (g.status || 'active') === 'active').length}</div><div className="mini-label">Active contacts</div></div>
          <div className="mini-stat"><div className="mini-value">+972</div><div className="mini-label">Required phone format</div></div>
          <div className="mini-stat"><div className="mini-value">No</div><div className="mini-label">Separate account needed</div></div>
        </div>

        <div className="card card-pad">
          <div className="flex-between mb-16">
            <div>
              <div className="card-title" style={{marginBottom:0}}>Guardian Contact Records</div>
              <p className="text-muted" style={{marginTop:6}}>No hard 3-guardian limit is enforced by this UI. Keep the list reasonable for SMS costs and demo clarity.</p>
            </div>
          </div>

          {showAdd && (
            <form className="inline-form mb-24" onSubmit={saveGuardian}>
              <div style={{display:'grid',gridTemplateColumns:'1fr 1fr',gap:12,marginBottom:12}}>
                <div><label className="form-label">Name</label><input className="form-input" placeholder="Jane Smith" value={newGuard.name} onChange={e => setNewGuard(g => ({...g, name: e.target.value}))} required /></div>
                <div><label className="form-label">Phone</label><input className="form-input" placeholder="+972507776403" value={newGuard.phone} onChange={e => setNewGuard(g => ({...g, phone: e.target.value}))} required /><div className="input-help">Must start with +972. Local 050/052 and obvious fake numbers are rejected.</div></div>
                <div><label className="form-label">Email optional</label><input className="form-input" type="email" placeholder="guardian@email.com" value={newGuard.email} onChange={e => setNewGuard(g => ({...g, email: e.target.value}))} /></div>
                <div><label className="form-label">Relationship</label><input className="form-input" placeholder="Daughter / Son / Caregiver" value={newGuard.relationship} onChange={e => setNewGuard(g => ({...g, relationship: e.target.value}))} /></div>
              </div>
              <div style={{display:'flex',gap:8}}>
                <button className="btn btn-primary btn-sm" disabled={saving}>{saving ? <Spinner/> : 'Save Guardian'}</button>
                <button type="button" className="btn btn-ghost btn-sm" onClick={() => {setShowAdd(false); setError('');}}>Cancel</button>
              </div>
            </form>
          )}

          {guardians.length === 0 && !showAdd && <EmptyState title="No guardians added yet" text="Add a trusted family member or caregiver to receive alerts." action={<button className="btn btn-primary btn-sm" style={{marginTop:12}} onClick={() => setShowAdd(true)}>Add Guardian</button>} />}

          <div className="guardian-list">
            {guardians.map((g, i) => (
              <div className="guardian-card" key={g.guardianId || i}>
                <div>
                  <div style={{fontWeight:700}}>{g.name}</div>
                  <div className="text-muted">{g.phone}</div>
                  <div className="guardian-meta"><span>{g.relationship || 'Family member'}</span><span>•</span><span>{g.email || 'No email'}</span><span>•</span><span>{g.status || 'active'}</span></div>
                </div>
                <button className="btn btn-ghost btn-sm" onClick={() => removeGuardian(i)} disabled={saving}>Remove</button>
              </div>
            ))}
          </div>
        </div>
      </main>
    </div>
  );
}

