// src/services/api.js
import axios from 'axios';
import config from '../config';
import { getToken } from './auth';

const api = axios.create({ baseURL: config.API_URL });

api.interceptors.request.use(async (req) => {
  const token = await getToken();
  if (token) req.headers.Authorization = `Bearer ${token}`;
  return req;
});

api.interceptors.response.use(
  r => r,
  err => Promise.reject(new Error(
    err.response?.data?.message || err.response?.data?.error || err.message || 'Request failed'
  ))
);


function normalizeIsraeliPhone(raw) {
  return String(raw || '').replace(/[\s\-()]/g, '');
}

function validateIsraeliPhone(raw) {
  const phone = normalizeIsraeliPhone(raw);
  if (!phone) throw new Error('Guardian phone is required.');
  if (phone.startsWith('0')) throw new Error('Use international format: +972..., not local 050/052 format.');
  if (!phone.startsWith('+972')) throw new Error('Guardian phone must start with +972.');
  if (!/^\+972[2-9]\d{7,8}$/.test(phone)) throw new Error('Guardian phone must be a valid Israeli E.164 number, for example +972507776403.');
  const digits = phone.slice(1);
  if (/^(\d)\1{8,}$/.test(digits) || /123123|123456|000000|111111/.test(digits)) throw new Error('Guardian phone looks fake. Use a real phone number.');
  return phone;
}

function normalizeGuardian(g = {}) {
  return {
    guardianId: g.guardianId,
    name: g.name || g.guardianName || '',
    phone: g.phone || g.guardianPhone || g.phoneNumber || '',
    email: g.email || g.guardianEmail || '',
    relationship: g.relationship || 'Family member',
    status: g.status || 'active',
    createdAt: g.createdAt,
    updatedAt: g.updatedAt,
  };
}

function normalizeSignal(signal) {
  if (typeof signal === 'string') return signal;
  if (!signal) return '';
  return signal.keyword || signal.reason || JSON.stringify(signal);
}

function normalizeEvent(ev = {}) {
  return {
    ...ev,
    eventId: ev.eventId || ev.callId || ev.contactId,
    timestamp: ev.timestamp || ev.createdAt || ev.startedAt,
    riskLevel: String(ev.riskLevel || ev.status || 'low').toLowerCase(),
    detectedSignals: (ev.detectedSignals || ev.topics || ev.detectedTopics || []).map(normalizeSignal).filter(Boolean),
    action: ev.action || (ev.disconnected ? 'disconnected' : ev.shouldAlert ? 'alert_sent' : 'none'),
    guardianNotified: ev.guardianNotified ?? ev.alertSent ?? ev.shouldAlert ?? ((ev.smsResult?.sentCount || 0) > 0),
    transcript: ev.transcript || ev.transcriptText || '',
    contactId: ev.contactId || ev.connectContactId || ev.callId,
    duration: ev.durationSeconds || ev.duration,
  };
}

function normalizeUser(user = {}) {
  return {
    ...user,
    userId: user.userId,
    name: user.name || user.email || 'New User',
    email: user.email || '',
    phone: user.phone || user.phone_number || '',
    role: user.role || 'user',
    monitoringEnabled: user.monitoringEnabled ?? true,
    connectNumber: user.connectNumber || user.phone || 'Provisioning...',
    guardians: (user.guardians || []).map(normalizeGuardian),
    recentEvents: (user.recentEvents || []).map(normalizeEvent),
  };
}

// User
export const getMe = async () => {
  const r = await api.get('/users/me');
  return normalizeUser(r.data.user || r.data);
};

export const updateMe = async (body) => {
  const r = await api.put('/users/me', body);
  return normalizeUser(r.data.user || r.data);
};

// Guardians are contact records under the protected user's account, not login accounts.
export const getGuardians = async () => {
  const r = await api.get('/guardians');
  return (r.data.guardians || r.data.items || []).map(normalizeGuardian);
};

export const createGuardian = async (body) => {
  const payload = {
    guardianName: body.name || body.guardianName,
    guardianPhone: validateIsraeliPhone(body.phone || body.guardianPhone),
    guardianEmail: body.email || body.guardianEmail || '',
    relationship: body.relationship || 'Family member',
    status: 'active',
  };
  const r = await api.post('/guardians', payload);
  return normalizeGuardian(r.data.guardian || r.data.item || r.data);
};

export const deleteGuardian = async (guardianId) => {
  const r = await api.delete(`/guardians/${guardianId}`);
  return r.data;
};

// Events
export const getEvents = async (params) => {
  const r = await api.get('/events', { params });
  return {
    events: (r.data.events || r.data.items || []).map(normalizeEvent),
    nextToken: r.data.nextToken,
  };
};

export const getEvent = async (id) => {
  const r = await api.get(`/events/${id}`);
  return normalizeEvent(r.data.event || r.data);
};

// Admin
export const getAdminStats = () => api.get('/admin/stats').then(r => r.data);

export const getAdminEvents = async (params) => {
  const r = await api.get('/admin/events', { params });
  return {
    events: (r.data.events || r.data.items || []).map(normalizeEvent),
    nextToken: r.data.nextToken,
  };
};

export const getAdminUsers = async (params) => {
  const r = await api.get('/admin/users', { params });
  return {
    users: (r.data.users || r.data.items || []).map(normalizeUser),
    nextToken: r.data.nextToken,
  };
};
export const getAdminUser = async (id) => {
  const r = await api.get(`/admin/users/${id}`);
  return normalizeUser(r.data.user || r.data);
};
export const updateAdminUser = (id, b) => api.put(`/admin/users/${id}`, b).then(r => r.data.user || r.data);

// Settings
export const getSettings = () => api.get('/settings').then(r => r.data);
export const updateSettings = (body) => api.put('/settings', body).then(r => r.data);
