// src/services/auth.js
// Wraps amazon-cognito-identity-js for all auth operations.
// Registration → Cognito signUp → email verification → PostConfirmation Lambda → DynamoDB record created.
import {
  CognitoUserPool,
  CognitoUser,
  AuthenticationDetails,
  CognitoUserAttribute,
} from 'amazon-cognito-identity-js';
import config from '../config';

const userPool = new CognitoUserPool({
  UserPoolId: config.USER_POOL_ID,
  ClientId:   config.USER_POOL_CLIENT_ID,
});

// ── Register ─────────────────────────────────────────────────────
// This Cognito pool is configured with email aliases. In that setup, the
// Cognito Username must NOT itself be an email address. We generate a hidden
// technical username and store the real email in the email attribute. Users
// can still sign in with their email alias after verification.
function buildSignupUsername(email) {
  const localPart = String(email || '')
    .toLowerCase()
    .trim()
    .split('@')[0]
    .replace(/[^a-z0-9_-]/g, '_')
    .replace(/_+/g, '_')
    .slice(0, 32) || 'user';

  const stamp = Date.now().toString(36);
  const random = Math.random().toString(36).slice(2, 8);
  return `sg_${localPart}_${stamp}_${random}`;
}

export function register({ name, email, phone, password }) {
  return new Promise((resolve, reject) => {
    const cleanEmail = email.toLowerCase().trim();
    const username = buildSignupUsername(cleanEmail);

    const attrs = [
      new CognitoUserAttribute({ Name: 'name',  Value: name.trim() }),
      new CognitoUserAttribute({ Name: 'email', Value: cleanEmail }),
    ];
    if (phone) {
      attrs.push(new CognitoUserAttribute({ Name: 'phone_number', Value: phone }));
    }

    userPool.signUp(username, password, attrs, [], (err, result) => {
      if (err) return reject(new Error(err.message));
      resolve({ result, username, email: cleanEmail });
    });
  });
}



// ── Confirm signup ───────────────────────────────────────────────
// Cognito ConfirmSignUp requires the Cognito technical username. Because this
// pool uses email as an alias, the username is a hidden generated value, not
// the email address. We store it right after signUp and use it here.
export function confirmRegistration(username, code) {
  return new Promise((resolve, reject) => {
    const user = new CognitoUser({ Username: username, Pool: userPool });
    user.confirmRegistration(String(code).trim(), true, (err, result) => {
      if (err) return reject(new Error(err.message));
      resolve(result);
    });
  });
}

// ── Resend signup code ───────────────────────────────────────────
export function resendRegistrationCode(username) {
  return new Promise((resolve, reject) => {
    const user = new CognitoUser({ Username: username, Pool: userPool });
    user.resendConfirmationCode((err, result) => {
      if (err) return reject(new Error(err.message));
      resolve(result);
    });
  });
}

// ── Login ─────────────────────────────────────────────────────────
export function login(email, password) {
  return new Promise((resolve, reject) => {
    const user    = new CognitoUser({ Username: email.toLowerCase().trim(), Pool: userPool });
    const details = new AuthenticationDetails({ Username: email.toLowerCase().trim(), Password: password });
    user.authenticateUser(details, {
      onSuccess: (session) => {
        const payload = session.getIdToken().decodePayload();
        const groups  = payload['cognito:groups'] || [];
        resolve({
          userId: payload.sub,
          email:  payload.email,
          name:   payload.name,
          groups: Array.isArray(groups) ? groups : [groups],
          token:  session.getIdToken().getJwtToken(),
        });
      },
      onFailure: (err) => reject(new Error(err.message)),
    });
  });
}

// ── Logout ────────────────────────────────────────────────────────
export function logout() {
  const user = userPool.getCurrentUser();
  if (user) user.signOut();
}

// ── Get current session token ─────────────────────────────────────
export function getToken() {
  return new Promise((resolve) => {
    const user = userPool.getCurrentUser();
    if (!user) return resolve(null);
    user.getSession((err, session) => {
      if (err || !session?.isValid()) return resolve(null);
      resolve(session.getIdToken().getJwtToken());
    });
  });
}

// ── Get current user info (groups etc.) ──────────────────────────
export function getCurrentUser() {
  return new Promise((resolve) => {
    const user = userPool.getCurrentUser();
    if (!user) return resolve(null);
    user.getSession((err, session) => {
      if (err || !session?.isValid()) return resolve(null);
      const payload = session.getIdToken().decodePayload();
      const groups  = payload['cognito:groups'] || [];
      resolve({
        userId: payload.sub,
        email:  payload.email,
        name:   payload.name,
        groups: Array.isArray(groups) ? groups : groups ? [groups] : [],
        token:  session.getIdToken().getJwtToken(),
      });
    });
  });
}
